using System;

namespace StdbModule;

public static partial class PolishQuotes
{
    public static class StanisławLem
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Nauka nie zajmuje się takimi własnościami bytu, do których należy śmieszność. Nauka objaśnia świat, ale pogodzić z nim może jedynie sztuka.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Pragniesz żyć, to jest posiadać przyszłość, która staje się teraźniejszością, do tego bowiem sprowadza się przecież życie.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Wszystko, cokolwiek istnieje, bywa przedmiotem drwin. Nie ostoi się wobec nich żadna godność, wiadomo bowiem, że ten i ów śmie podrwiwać nawet z królewskiego majestatu.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Ignorancja nasza (ludzka) jest oceanem ogólnoświatowym, zaś wiedza pewna – pojedynczymi wysepkami na tym oceanie.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Każda bez wyjątku nowa technologia ma awers korzyści i zarazem rewers nowych, nieznanych dotychczas bied.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Świadomość jest jak wiatr, o którym można powiedzieć, iż wieje, ale nie ma sensu pytać, gdzie jest wiatr, kiedy nie wieje.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Na szczyt można wejść, ale wszystkie drogi ze szczytu prowadzą w dół!", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Już dziś go wyprzedzają. Byle elektryczna maszyna do liczenia rozwiąże zadanie, któremu przez całe życie nie podoła najlepszy matematyk.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Jak wiadomo, padalce nie szybują w przestworzach, ponieważ im na tym nie zależy.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Kupiec niewolników, sortując towar, krzepkich mężów przeznaczał do kopalni, niewiasty do kuchni, a młodzież nie znającą ortografii na rozkurz.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Smutny jest żywot tasiemca. Należy on do istot głuchoniemych i ślepych, czyli jest dożywotnim kaleką. Nie ma także rąk ani nóg", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "W kałuży krwi leżał trup świeży, lecz sztywny, z wyrazem zasmucenia na twarzy, której niewiele mu zresztą zostało.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Wątróbkę, nieboszczykowi niepotrzebną, z wnętrzności wyjmujemy i wkładamy do lodówki. Trupa wyrzucamy lub stawiamy w zbożu jako stracha na wróble.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Wspominając wieczerzę, wykrzykują: „Jakiż to był dobry, delikatny i lekkostrawny człowiek!”", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Duizm głosi, że każde życie zna dwie śmierci, przednią i tylną, to jest tę sprzed narodzin i tę po agonii.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Holiści-pluraliści-behawioryści-fizykaliści orzekli, iż jak wiadomo z fizyki, prawidłowość w naturze jest tylko statystyczna.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Jak można się nie przekształcać, jeżeli można się przekształcać?", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Kiedy można być każdym i żywić dowolne przekonania, nie jest się już nikim i nie ma się żadnych przekonań.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Nie ma sprawiedliwości tam, gdzie jest prawo głoszące wolność najwyższą…", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Przyroda postąpiła z nami jak łotr (…). Im kto bardziej w życiu zmądrzeje, tym bliżej do jamy.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Śruba, przykręcona we śnie, nie zmieni sytuacji, jaka panuje na jawie.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Wiedza unicestwia stopniowo dyrektywy, zwane przykazaniami objawionymi. Pozwala ona zabijać, nie zabijając, niszczyć, lecz tak, że to niszczenie stwarza.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Zauważ, proszę, że świat zniewolony do samego dobra jest takim samym przybytkiem niewoli jak świat zniewolony do samego zła.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Astronautyka to czysty niepokalany płód ludzkiej ciekawości.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Na wszystko, co się zdarzy, masz gotowy, przywieziony z Ziemi schemat. Jeżeli jakiś szczegół nie pasuje, to go po prostu odrzucasz.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Wiecie czego tu najbardziej brak? Trawy, zwykłej trawy. Nigdy nie przypuszczałem, że jest tak… potrzebna…", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Przyszłość jest co najmniej podwójnie indeterministyczna: z jednej strony niedookreślona przez to, co stanowi obszar realnej swobody decyzyjnej wielkich ugrupowań społecznych Ziemi", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Gdyby ludzie od jaskiniowej epoki robili tylko to, co wyglądało na możliwe, do dzisiaj siedzieliby w jaskiniach.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Wysoka technologia nie wyklucza wierzeń religijnego typu.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Poznanie jest zdobyciem pewności w jakiejkolwiek kwestii; otóż nie ma żadnego sposobu, który by mógł głód pewności zaspokoić, jeśli jest on tylko odpowiednio nieposkromiony.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Jednakowoż wiemy teraz na pewno, że gdy po planetach będą się przechadzali pierwsi wysłannicy Ziemi, inni jej synowie nie o wyprawach takich będą marzyć, lecz o kawałku chleba.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Cywilizacja zaczyna się od bieżącej wody. Klozety króla Minosa na Krecie.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Ludzkość tak się rozmnożyła i zgęściła, że zaczynają nią rządzić prawa atomowe.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Proroctwa McLuhana spełniają się, ale na opak, jak to zwykle bywa z proroctwami.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Istniał aerozol – krypto­bellina – o radykalnym działaniu wojennym; kto go łyknął, sam biegł za postronkiem i wiązał się jak baran.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "jeśli ktoś sobie roi, że sobie roi, że sobie nic nie roi – albo na odwrót…", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Jeżeli nie można odmienić prawdy, trzeba ją zasłonić, to ostatni jeszcze humanitarny, jeszcze ludzki obowiązek.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Rohan (…) szedł prosto na dwudziestopiętrowy statek, który stał w powodzi świateł, na tle blednącego nieba, tak majestatyczny w swym nieruchomym ogromie, jakby naprawdę był niezwyciężony.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Odwrotna proporcjonalność liczby żyjących do wagi i godności indywidualnej egzystencji jest faktem.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Powiedziałbym, że sytuacja nasza przypomina genialną myśl dzikusa, który, odkrywszy zasadę procy, uznał, że niedaleko mu już do lotów kosmicznych.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Seks zbratany z pieniądzem staną się świetnie podrobionymi rajami doczesności.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Starożytni mawiali: „mundus vult decipi, ergo decipiatur”. Świat łaknie oszustw, więc jest oszukiwany.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Technocywilizacyjna działalność człowieka coraz silniej, a nawet coraz groźniej wpływa na klimat planety.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Większość fikcji beletrystycznych napisała mi się w tym rozumieniu sama, że pisałem, nie znając z góry ani fabularnego schematu, ani przebiegu akcji, ani jej miejsc węzłowych, ani wreszcie finału.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Wszystko jest znacznie bardziej skomplikowane, aniżeli zdolny byłby pojąć umysł człowieka, który stroniąc od eksperymentalnej nauki, pragnie się schronić w królestwie filozoficznego myślenia.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Kobiety z niektórymi faktami nie chcą się pogodzić. Mówią dalej „nie”, nawet jeśli już nic oprócz „tak” powiedzieć nie można.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Rzekomy trening był nieodwołalną rzeczywistością; wstęp – treścią właściwą; nadzieje – mrzonkami; nie obowiązujące zaś, prowizoryczne, tymczasowe i byle jakie – jedyną zawartością życia.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Dobrobyt, rozszalały po przeprowadzce zbrojeń na Księżyc, miał, w połączeniu z automatyzacją przemysłu, dość ponure skutki.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Do zagłady nie jest wcale potrzebna wojna, atomowa albo i nieatomowa, skoro doprowadzą do niej eskalacyjne koszty dalszych zbrojeń.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Kiedy stawka jest dostatecznie wysoka, prawo przestaje się liczyć.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Kiedy technicy nie wiedzą co się dzieje, bogactwem słownictwa dorównują lekarzom przy konsylium nad beznadziejnym przypadkiem.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Kto sieje ewolucję, ten zbiera rozum. A rozum nie chce nikomu służyć.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Nie ma dobrej odpowiedzi na źle postawione pytanie.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Normalny człowiek jest istotą wysoce nielogiczną i w tym jego człowieczeństwo.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "To ja wykryłem Prawo Tichego, powiadające, że jako pierwsza zaczyna świerzbić i łaskotać ta część ciała, w którą żadnym sposobem nie można się podrapać.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Była to cywilizacja pozbawiona lęku. Wszystko, co istniało, służyło ludziom. Nic nie miało wagi, prócz ich wygody, zaspokojenia potrzeb oczywistych i najbardziej wyszukanych.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Całe popołudnie spędziłem w księgarni. Nie było w niej książek. Nie drukowano ich już od pół wieku bez mała.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Co można mieć z gwiazd? A jaki były korzyści wyprawy Amundsena? Andréego? Żadne.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Myślę, że oni zrobili okropną rzecz. Oni zabili w człowieku – człowieka.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Ogół nie zdaje sobie z tego sprawy… (…) Z tego, że ginie duch eksploracji. Że nie ma wypraw, o tym wiedzą. Ale nie myślą o tym.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Pana zainteresowania, to, z czym pan wrócił, są wysepką w morzu ignorancji. Wątpię, czy wielu ludzi chciałoby słuchać tego, co ma pan do opowiedzenia.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Postęp nigdy nie przychodzi za darmo.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Tak więc uzyskanie prawa do dziecka było teraz szczególnym wyróżnieniem, nie przyznawanym byle komu; dalej, rodzice nie mogli izolować dzieci od ich rówieśników", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Trudno panu to zrozumieć. Ale argumenty rozumu są bezsilne wobec panującej obyczajowości.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Wiesz, co było naszym pechem, Bergg? To, że się nam powiodło i że siedzimy tu. Człowiek zawsze wraca z pustymi rękami…", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Zlikwidowaliśmy piekło namiętności, a wtedy okazało się, że za jednym zamachem i niebo przestało istnieć. Wszystko jest teraz letnie, Bregg.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Zrozumie pan, jakie są dziś kryteria erotycznego doboru. Najważniejszym jest młodość. Dlatego tak wszyscy o nią walczą.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "A teraz zgasimy światło i do rana nie będziemy mieli żadnych zmartwień, a rano, jeżeli się nam zechce, to postaramy się o nowe.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Kiedy chodziłem do szkoły, Solaris – za sprawą poznanych później faktów – powszechnie już była uznana za planetę obdarzoną życiem – tyle że posiadającą jednego tylko mieszkańca…", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Fantomatyka zdaje się stanowić swoisty szczyt, ku któremu zmierzają liczne techniki rozrywkowe współczesności.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Kosmos nie został stworzony dla nas ani my – dla niego. Jesteśmy ubocznym produktem gwiazdowych przemian i produktów, jakie Wszechświat wytwarzał i wytwarza ilości niezliczone.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Przy całej bowiem nierozstrzygalności empirycznej istnienia desygnatów wiary, jej wartość przystosowawcza, jako źródła informacji uniwersalnej, nie ulega wątpliwości.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Systemy metafizyczne, czy to po wschodniemu mgliste i aforystycznie wieloznaczne, czy operujące po europejsku wykształconą logiką, zawsze są proste w zestawieniu z rzeczywistą złożonością świata.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Tylko w powieści przed słowem „koniec” losy bohaterów nieruchomieją w figurze napawającej autora estetycznym zadowoleniem.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "– No taki chabaźnik, specjalista od mchów i porostów – mimo to objaśnił Sekułowski.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Pociąg stał w Nieczawach krótko.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "– Z czasów mojej terminatorki pamiętam kilka ciekawych, po prostu czystych form, wyhodowanych na pożywkach różnych środowisk literackich.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Pomału można doprowadzić nawet konklawe do kanibalizmu. Byle postępować stopniowo, krok za krokiem.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Perfekcja, pełnia, doskonałość – to rzadki wyjątek, zdarzający się tylko dlatego, że wszystkiego jest tak niesłychanie, niewyobrażalnie wiele!", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Religia, filozofia są klejem, wciąż składamy i zbieramy rozpełzające się w statystykę ochłapy, żeby je złożyć w sens, jak w dzwon naszej chwały, żeby odezwały się jednym, jedynym głosem!", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Utyskuje się dziś na powszechne obniżenie lotu sztuki, tkniętej trądem bezideowości, skazanej niewiadomymi wyrokami na miałkość przemijających eksperymentów i jednodniowej mody.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Jak wiadomo, wydawcy nie boją się niczego tak jak wydawania książek, gdyż w pełni już działa tak zwane prawo Lema („Nikt nie czyta; jeśli czyta, nic nie rozumie; jeśli rozumie, natychmiast zapomina”)", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Kiedy wszyscy są wariatami, nikt nie jest wariatem.", Author = "Stanisław Lem" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Lem", Text = "Wydelikaciła nas cywilizacja jak jagódki cieplarniane: pulchniśmy, rumiani, nie zahartowani dostatecznie, nie uwędzeni w dymie diabelskim!", Author = "Stanisław Lem" },
        };
    }
}